// Called by workflow 10 on conversion. Body: { email, name, tier }
const b = $input.first().json.body ?? $input.first().json;
if (!b.email) { throw new Error('Onboarding missing email'); }
return [{ json: { email: String(b.email).trim().toLowerCase(), name: b.name || String(b.email).split('@')[0], tier: b.tier || 'Foundation' } }];
